(function(){
const key='almeida-customer-session';const root=document.querySelector('#account-page-content');let session=null;
const api=(path,opt={})=>fetch(ALMEIDA_SUPABASE_URL+path,{...opt,headers:{apikey:ALMEIDA_SUPABASE_KEY,Authorization:'Bearer '+(session?.access_token||ALMEIDA_SUPABASE_KEY),'Content-Type':'application/json',...(opt.headers||{})}}).then(async r=>{const raw=await r.text();let data=raw?JSON.parse(raw):null;if(!r.ok)throw Error(data?.message||data?.error_description||'Não foi possível carregar sua conta.');return data});
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>(Number(c||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const first=v=>String(v||'').trim().split(/\s+/)[0]||'cliente';const addr=(a,k)=>a&&typeof a==='object'?a[k]||'':'';const status=s=>s==='pending'?'Aguardando confirmação':s==='confirmed'?'Venda confirmada':'Pedido cancelado';
function render(user,profile,orders){const name=profile?.full_name||user.user_metadata?.full_name||'',a=profile?.default_address||{};root.innerHTML=`<div class="account-hero"><small>ÁREA DO CLIENTE</small><h1>Minha Conta</h1><p>Olá, <strong>${esc(first(name))}</strong>! Aqui você acompanha seus dados e pedidos.</p></div><div class="account-grid"><section class="account-card"><div class="account-card-heading"><div><small>SEUS DADOS</small><h2>Dados pessoais</h2></div></div><form id="account-data-form" class="account-form"><label>Nome completo<input id="account-full-name" required value="${esc(name)}"></label><label>E-mail<input disabled value="${esc(user.email||profile?.email||'')}"></label><label>Data de nascimento<input id="account-birth-date" type="date" value="${esc(profile?.birth_date||'')}"></label><label>Telefone<input id="account-phone" type="tel" placeholder="(32) 99999-9999" value="${esc(profile?.phone||'')}"></label><div class="account-section-title"><small>ENDEREÇO</small><h3>Endereço padrão</h3></div><label>Rua<input id="account-street" value="${esc(addr(a,'street'))}"></label><div class="account-form-row"><label>Número<input id="account-number" value="${esc(addr(a,'number'))}"></label><label>Bairro<input id="account-neighborhood" value="${esc(addr(a,'neighborhood'))}"></label></div><label>Referência<input id="account-reference" placeholder="Opcional" value="${esc(addr(a,'reference'))}"></label><p id="account-data-feedback" class="account-feedback" role="status"></p><button class="primary" type="submit">Salvar dados</button></form></section><section id="pedidos" class="account-card account-orders"><div class="account-card-heading"><div><small>HISTÓRICO</small><h2>Meus Pedidos</h2></div><span class="account-count">${orders.length}</span></div><div>${orders.length?orders.map(o=>`<article class="order-card"><div class="order-heading"><strong>Pedido #${esc(o.public_number)}</strong><span>${status(o.status)}</span></div><small>${new Date(o.created_at).toLocaleString('pt-BR')} · ${o.payment_method==='pix'?'PIX':o.payment_method==='cash'?'Dinheiro':'Cartão'}</small><p>${(o.order_items||[]).map(i=>`${esc(i.quantity)}× ${esc(i.product_name)} — ${esc(i.variant_name)} · ${money(i.line_total_cents)}`).join('<br>')}</p><b>Total: ${money(o.amount_due_cents)}</b></article>`).join(''):'<p class="muted">Você ainda não tem pedidos registrados.</p>'}</div></section></div>`;document.querySelector('#account-data-form').onsubmit=saveProfile;document.querySelector('#account-phone').oninput=formatPhone;if(location.hash==='#pedidos')document.querySelector('#pedidos').scrollIntoView({behavior:'smooth'})}
function formatPhone(e){let n=e.target.value.replace(/\D/g,'').slice(0,11);e.target.value=n.length>10?'('+n.slice(0,2)+') '+n.slice(2,7)+'-'+n.slice(7):n.length>2?'('+n.slice(0,2)+') '+n.slice(2):n}
async function saveProfile(e){e.preventDefault();const f=document.querySelector('#account-data-feedback');f.textContent='Salvando...';try{await api('/rest/v1/profiles?id=eq.'+encodeURIComponent(session.user.id),{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({full_name:document.querySelector('#account-full-name').value.trim(),phone:document.querySelector('#account-phone').value.trim(),birth_date:document.querySelector('#account-birth-date').value||null,default_address:{street:document.querySelector('#account-street').value.trim(),number:document.querySelector('#account-number').value.trim(),neighborhood:document.querySelector('#account-neighborhood').value.trim(),reference:document.querySelector('#account-reference').value.trim()}})});f.textContent='Dados salvos com sucesso.'}catch(x){f.textContent=x.message;f.classList.add('error')}}
async function start(){try{session=JSON.parse(localStorage.getItem(key)||'null');if(!session?.access_token)throw Error('Entre na sua conta para acessar esta página.');const user=await api('/auth/v1/user');session.user=user;const [profiles,orders]=await Promise.all([api('/rest/v1/profiles?select=full_name,email,phone,birth_date,default_address&id=eq.'+encodeURIComponent(user.id)),api('/rest/v1/orders?select=id,public_number,status,payment_method,amount_due_cents,created_at,order_items(product_name,variant_name,quantity,line_total_cents)&order=created_at.desc')]);render(user,profiles?.[0]||{},orders||[])}catch(x){root.innerHTML='<div class="account-empty"><h1>Minha Conta</h1><p>'+esc(x.message)+'</p><a class="primary-link" href="index.html">Voltar ao catálogo e entrar</a></div>'}}
document.querySelector('#account-signout').onclick=async()=>{try{if(session?.access_token)await fetch(ALMEIDA_SUPABASE_URL+'/auth/v1/logout',{method:'POST',headers:{apikey:ALMEIDA_SUPABASE_KEY,Authorization:'Bearer '+session.access_token}})}finally{localStorage.removeItem(key);location.href='index.html'}};start();
})();
